INSERT OR IGNORE INTO knowledge_items (id, category, title, content, status) VALUES ('kb_unknown_unlisted_product_warning','product_process','Unknown or unlisted product handling','English: This product is not yet available in the approved Tonlita knowledge base. You may continue qualifying the customer, but technical and commercial facts must be confirmed before they are communicated. Chinese: 该产品目前尚未录入 Tonlita 已批准的知识库。您可以继续了解客户需求，但在向客户提供技术或商务信息之前，必须先进行内部确认。','approved');
